INSERT INTO hall.document_template (kind, document_type, name, body_markdown, subject, stylesheet, header_html, footer_html)
SELECT 'pdf', 'document-print', 'Impression de document',
  '{# hall:jinja #}
{{ generated.bodyMarkdown | markdown }}', NULL, 'h1, h2, h3, h4 { break-after: avoid; } p:has(+ blockquote) { break-after: avoid; } p, li { orphans: 3; widows: 3; } table { break-inside: avoid; }', '{{ hall.name | text }}', 'Page :page-number / :page-count'
WHERE NOT EXISTS (SELECT FROM hall.document_template WHERE kind = 'pdf' AND document_type = 'document-print');
